-- Exact function-body checks plus ledger, column, triggers and permissions.
WITH checks(name,ok) AS (
 SELECT 'ledger',EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261111000000' AND name='question_practice_option_order' AND cardinality(statements)=1 AND md5(statements[1])='8e115580c1dc373968f8a465c4537429')
 UNION ALL SELECT 'question_practice_items_shuffle_options',coalesce((SELECT md5(prosrc)='86a865a35b92a287662e11ad712c9748' AND prosecdef=false AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_items_shuffle_options()')),false)
 UNION ALL SELECT 'question_practice_items_arena_order',coalesce((SELECT md5(prosrc)='029aa247b217c893ef5f0b4361a715b8' AND prosecdef=false AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_items_arena_order()')),false)
 UNION ALL SELECT 'question_practice_snapshot_questions',coalesce((SELECT md5(prosrc)='e8ea3e7c5d57dd02a30bb90425be8de6' AND prosecdef=true AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_snapshot_questions(uuid)')),false)
 UNION ALL SELECT 'private_question_practice_items_shuffle_options',NOT has_function_privilege('authenticated','public.question_practice_items_shuffle_options()','EXECUTE') AND NOT has_function_privilege('anon','public.question_practice_items_shuffle_options()','EXECUTE')
 UNION ALL SELECT 'private_question_practice_items_arena_order',NOT has_function_privilege('authenticated','public.question_practice_items_arena_order()','EXECUTE') AND NOT has_function_privilege('anon','public.question_practice_items_arena_order()','EXECUTE')
 UNION ALL SELECT 'private_question_practice_snapshot_questions',NOT has_function_privilege('authenticated','public.question_practice_snapshot_questions(uuid)','EXECUTE') AND NOT has_function_privilege('anon','public.question_practice_snapshot_questions(uuid)','EXECUTE')
 UNION ALL SELECT 'question_practice_items_shuffle_options',EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='question_practice_items_shuffle_options' AND tgrelid='public.question_practice_items'::regclass AND tgenabled='O' AND NOT tgisinternal AND pg_get_triggerdef(oid) LIKE '%BEFORE INSERT%')
 UNION ALL SELECT 'question_practice_items_arena_order',EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='question_practice_items_arena_order' AND tgrelid='public.arena_practice_issues'::regclass AND tgenabled='O' AND NOT tgisinternal AND pg_get_triggerdef(oid) LIKE '%AFTER INSERT%')
 UNION ALL SELECT 'option_order_column',EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='question_practice_items' AND column_name='option_order' AND data_type='ARRAY' AND is_nullable='YES')
 UNION ALL SELECT 'items_read_only',NOT has_table_privilege('authenticated','public.question_practice_items','INSERT,UPDATE,DELETE')
 UNION ALL SELECT 'get_practice_rpc',has_function_privilege('authenticated','public.get_question_practice(uuid)','EXECUTE')
) SELECT jsonb_build_object('all_checks_pass',bool_and(ok),'checks',jsonb_agg(jsonb_build_object('name',name,'ok',ok) ORDER BY name)) AS option_order_verification FROM checks;
